from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return not stack

    def extract_groups(s: str) -> List[str]:
        groups = []
        group = ''
        for char in s:
            if char == '(':
                if group:
                    groups.append(group)
                group = '('
            elif char == ')':
                group += ')'
        groups.append(group)
        return groups

    paren_string = paren_string.replace(' ', '')
    groups = extract_groups(paren_string)
    balanced_groups = [group for group in groups if is_balanced(group)]

    return balanced_groups

